64	    public Collection<String> create(Collection<ClassInfo> classInfos) {
65	        Set<String> createdClasses = new HashSet<>();
66	        toBeGenerated.addAll(classInfos);
67	
68	        while (!toBeGenerated.isEmpty()) {
