75	    private Optional<String> create(ClassInfo classInfo) {
76	        String beanClassName = classInfo.name().toString();
77	        if (vetoedClass(classInfo, beanClassName) || !generatedClassNames.add(beanClassName)) {
78	            return Optional.empty();
79	        }
80	
81	        String generatedClassName = beanClassName + getClassSuffix();
82	
83	        try (ClassCreator classCreator = new ClassCreator(
84	                new GeneratedClassGizmoAdaptor(generatedClassBuildItemBuildProducer, true), generatedClassName, null,
85	                getSuperClassName(), getInterfacesNames(classInfo))) {
86	
87	            createConstructor(classCreator, beanClassName);
88	            boolean valid = createSerializationMethod(classInfo, classCreator, beanClassName);
89	            return valid ? Optional.of(generatedClassName) : Optional.empty();
90	        }
91	    }
